begin;
revoke usage on schema auth from castly_api;
create schema phase6_test;
create function phase6_test.eq(actual bigint,expected bigint,label text) returns void language plpgsql as $$begin if actual is distinct from expected then raise exception 'FAIL %: got %, expected %',label,actual,expected;end if;raise notice 'PASS %',label;end$$;
create function phase6_test.denied(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL unauthorized SQL: %',label;end$$;
grant usage on schema phase6_test to castly_api,authenticated,castly_engagement_worker;
grant execute on all functions in schema phase6_test to castly_api,authenticated,castly_engagement_worker;
insert into auth.users(id,raw_user_meta_data) values('60000000-0000-0000-0000-000000000001','{}'),('60000000-0000-0000-0000-000000000002','{}');
insert into public.engagement_preferences(user_id) values('60000000-0000-0000-0000-000000000002');
insert into public.push_devices(user_id,device_key,token,platform) values('60000000-0000-0000-0000-000000000002',gen_random_uuid(),'ExpoPushToken[private_fixture_token_other]','android');
select phase6_test.eq((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relrowsecurity and(n.nspname='engagement_private' or n.nspname='public' and c.relname in('engagement_preferences','push_devices','saved_searches'))),12,'all Phase6 tables use RLS');
select phase6_test.eq((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='engagement_private' and p.prosecdef),0,'no privileged Phase6 functions');
select phase6_test.eq(has_column_privilege('castly_engagement_worker','public.bookings','requirements','SELECT')::int,0,'worker cannot read booking prose');
select phase6_test.eq(has_table_privilege('castly_engagement_worker','public.messages','SELECT')::int,0,'worker cannot read message bodies');
select phase6_test.eq(has_schema_privilege('castly_engagement_worker','auth','USAGE')::int,0,'worker has no auth schema access');
select phase6_test.eq(has_schema_privilege('castly_api','auth','USAGE')::int,0,'API needs no auth schema access');
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000001',true);
select set_config('castly.phase6.subject',repeat('a',64),true);
set local role authenticated;
select phase6_test.denied('select * from public.push_devices','direct mobile token access denied');
select phase6_test.denied('select * from engagement_private.outbox','direct mobile outbox access denied');
reset role;
set local role castly_api;
select phase6_test.eq((select count(*) from public.push_devices),0,'other actor token hidden');
select phase6_test.eq((select count(*) from public.engagement_preferences),0,'other actor preferences hidden');
insert into public.engagement_preferences(user_id,analytics) values(private.request_user_id(),true);
select phase6_test.denied($q$insert into public.push_devices(user_id,device_key,token,platform) values('60000000-0000-0000-0000-000000000002',gen_random_uuid(),'ExpoPushToken[forged_fixture_token_other]','ios')$q$,'cannot register another actor device');
select phase6_test.denied($q$insert into engagement_private.contacts(user_id,email,verified_at) values(private.request_user_id(),'forged@fixture.invalid',now())$q$,'cannot forge verified email');
select phase6_test.denied($q$insert into engagement_private.analytics_admins values(private.request_user_id())$q$,'cannot self grant analytics admin');
select phase6_test.denied($q$insert into engagement_private.events(subject_key,event) values(repeat('b',64),'search')$q$,'cannot impersonate analytics actor');
select phase6_test.denied($q$insert into engagement_private.outbox(recipient_id,event_key,kind,channel) values(private.request_user_id(),'fake','account_activity','email')$q$,'cannot forge outbox event');
select phase6_test.denied($q$select engagement_private.enqueue(private.request_user_id(),'fake','account_activity',null,null,null,null,null)$q$,'direct enqueue cannot bypass source trigger');
select phase6_test.denied($q$insert into engagement_private.schedule_sources(user_id,kind,source_id,local_day,event_key) values(private.request_user_id(),'reengagement',private.request_user_id(),current_date,'forged')$q$,'scheduler cannot ignore consent/source');
select set_config('castly.phase6.push','false',true),set_config('castly.phase6.email','false',true);
update public.engagement_preferences set reengagement=true,last_active_at=statement_timestamp()-interval '15 days' where user_id=private.request_user_id();
insert into engagement_private.schedule_sources(user_id,kind,source_id,local_day,event_key)
 select private.request_user_id(),'reengagement',private.request_user_id(),current_date,'reengagement:'||private.request_user_id()||':'||date_trunc('week',current_date::timestamp)::date on conflict do nothing;
insert into engagement_private.schedule_sources(user_id,kind,source_id,local_day,event_key)
 select private.request_user_id(),'reengagement',private.request_user_id(),current_date,'reengagement:'||private.request_user_id()||':'||date_trunc('week',current_date::timestamp)::date on conflict do nothing;
select phase6_test.eq((select count(*) from engagement_private.schedule_sources where kind='reengagement'),1,'consented reengagement dedupes within local week');
update public.engagement_preferences set reengagement=false where user_id=private.request_user_id();
select phase6_test.denied($q$insert into engagement_private.schedule_sources(user_id,kind,source_id,local_day,event_key) select private.request_user_id(),'reengagement',private.request_user_id(),current_date,'reengagement:'||private.request_user_id()||':'||date_trunc('week',current_date::timestamp)::date on conflict do nothing$q$,'withdrawn reengagement cannot queue');
select phase6_test.eq((select count(*) from engagement_private.analytics_admins),0,'admin roster is isolated');
reset role;
set local role castly_engagement_worker;
select phase6_test.eq((select count(*) from public.push_devices where user_id='60000000-0000-0000-0000-000000000002'),0,'worker cannot enumerate devices without delivery sources');

select phase6_test.denied($q$update public.users set display_name='spoofed'$q$,'worker cannot edit accounts');
select phase6_test.denied($q$update public.bookings set status='accepted'$q$,'worker cannot change bookings');
select phase6_test.denied($q$insert into engagement_private.analytics_admins values(gen_random_uuid())$q$,'worker cannot grant analytics admin');
reset role;
rollback;
